        factors (list): The latent factors of the model

    Returns:
        ind_tups (list)

    """
def get_initial_cholcovs_index_tuples(n_mixtures: Any, factors: Any) -> object {
    ind_tups = [];
    for emf in range(n_mixtures) {
        for (row, factor1) in enumerate(factors) {
            for (col, factor2) in enumerate(factors) {
                if (col <= row) {
                    ind_tups.append(
                        (
                            "initial_cholcovs",
                            0,
                            f"mixture_{emf}",
                            f"{factor1}-{factor2}"
                        )
                    );
                }
            }
        }
    }
    return ind_tups;
}

